// ২. সরাসরি ক্লাসের ভেতর (Class Body)
private android.widget.ListView listView;
private android.widget.ProgressBar progressBar;
private MyAdapter myAdapter;
private String pendingPkg = "";
private String pendingName = "";

private void loadAppList() {
    progressBar.setVisibility(android.view.View.VISIBLE);
    new Thread(() -> {
        android.content.pm.PackageManager pm = getPackageManager();
        android.content.Intent i = new android.content.Intent(android.content.Intent.ACTION_MAIN, null);
        i.addCategory(android.content.Intent.CATEGORY_LAUNCHER);
        java.util.List<android.content.pm.ResolveInfo> list = pm.queryIntentActivities(i, 0);

        // A-Z আকারে সাজানো
        java.util.Collections.sort(list, new android.content.pm.ResolveInfo.DisplayNameComparator(pm));

        final java.util.ArrayList<java.util.HashMap<String, Object>> data = new java.util.ArrayList<>();
        for (android.content.pm.ResolveInfo r : list) {
            if (r.activityInfo.packageName.equals(getPackageName())) continue;
            java.util.HashMap<String, Object> m = new java.util.HashMap<>();
            m.put("n", pm.getApplicationLabel(r.activityInfo.applicationInfo).toString());
            m.put("p", r.activityInfo.packageName);
            m.put("i", pm.getApplicationIcon(r.activityInfo.applicationInfo));
            data.add(m);
        }
        runOnUiThread(() -> {
            progressBar.setVisibility(android.view.View.GONE);
            myAdapter = new MyAdapter(data);
            listView.setAdapter(myAdapter);
        });
    }).start();
}

private void showMyLogs() {
    android.widget.ListView lv = new android.widget.ListView(this);
    lv.setAdapter(new android.widget.ArrayAdapter<>(this, android.R.layout.simple_list_item_1, CycleService.logList));
    new android.app.AlertDialog.Builder(this)
        .setTitle("Captured API/Links")
        .setView(lv)
        .setPositiveButton("OK", null)
        .show();
}

private void showConfirmDialog(String pkg, String name) {
    new android.app.AlertDialog.Builder(this)
        .setTitle("Firewall Warning")
        .setMessage("Block internet and monitor requests for " + name + "?")
        .setNegativeButton("Cancel", null) 
        .setPositiveButton("Yes", (d, w) -> {
            CycleService.blockedApps.add(pkg); // Service এর RAM-এ সেভ
            if (myAdapter != null) myAdapter.notifyDataSetChanged();
            android.content.Intent it = new android.content.Intent(MainActivity.this, CycleService.class);
            it.setAction("UPDATE");
            startService(it);
        }).show();
}

@Override
protected void onActivityResult(int req, int res, android.content.Intent d) {
    if (req == 101 && res == RESULT_OK) {
        showConfirmDialog(pendingPkg, pendingName);
    }
    super.onActivityResult(req, res, d);
}

class MyAdapter extends android.widget.BaseAdapter {
    java.util.ArrayList<java.util.HashMap<String, Object>> _d;
    MyAdapter(java.util.ArrayList<java.util.HashMap<String, Object>> d) { _d = d; }
    @Override public int getCount() { return _d.size(); }
    @Override public Object getItem(int i) { return _d.get(i); }
    @Override public long getItemId(int i) { return i; }
    @Override public android.view.View getView(int i, android.view.View v, android.view.ViewGroup p) {
        if (v == null) {
            android.widget.LinearLayout l = new android.widget.LinearLayout(MainActivity.this);
            l.setPadding(20, 30, 20, 30); l.setGravity(16);
            android.widget.ImageView img = new android.widget.ImageView(MainActivity.this);
            l.addView(img, 110, 110);
            android.widget.TextView t = new android.widget.TextView(MainActivity.this);
            t.setPadding(30, 0, 0, 0); t.setTextSize(16);
            l.addView(t, new android.widget.LinearLayout.LayoutParams(0, -2, 1f));
            android.widget.Switch s = new android.widget.Switch(MainActivity.this);
            l.addView(s); v = l;
        }
        java.util.HashMap<String, Object> m = _d.get(i);
        String pkg = m.get("p").toString();
        String name = m.get("n").toString();

        android.widget.Switch sw = (android.widget.Switch)((android.view.ViewGroup)v).getChildAt(2);
        ((android.widget.TextView)((android.view.ViewGroup)v).getChildAt(1)).setText(name);
        ((android.widget.ImageView)((android.view.ViewGroup)v).getChildAt(0)).setImageDrawable((android.graphics.drawable.Drawable)m.get("i"));

        sw.setOnCheckedChangeListener(null);
        sw.setChecked(CycleService.blockedApps.contains(pkg)); // Service এর RAM থেকে চেক

        sw.setOnClickListener(view -> {
            if (CycleService.blockedApps.contains(pkg)) {
                // আনসিলেক্ট করার লজিক (Unselect Fix)
                CycleService.blockedApps.remove(pkg);
                notifyDataSetChanged();
                android.content.Intent it = new android.content.Intent(MainActivity.this, CycleService.class);
                if (CycleService.blockedApps.isEmpty()) {
                    it.setAction("STOP"); // অ্যাপ ফাঁকা হলে পুরোপুরি ভিপিএন বন্ধ করবে
                } else {
                    it.setAction("UPDATE"); // অন্য অ্যাপ থাকলে শুধু আপডেট করবে
                }
                startService(it);
            } else {
                sw.setChecked(false); 
                android.content.Intent intent = android.net.VpnService.prepare(MainActivity.this);
                if (intent != null) {
                    pendingPkg = pkg;
                    pendingName = name;
                    startActivityForResult(intent, 101);
                } else {
                    showConfirmDialog(pkg, name);
                }
            }
        });
        return v;
    }
}

// ম্যানিফেস্টের নাম অনুযায়ী CycleService
public static class CycleService extends android.net.VpnService {
    private android.os.ParcelFileDescriptor vpn = null;

    // RAM স্টোরেজ এখন সার্ভিসের ভেতরে (সোয়াইপ করলেও বাঁচবে!)
    public static java.util.HashSet<String> blockedApps = new java.util.HashSet<>();
    public static java.util.ArrayList<String> logList = new java.util.ArrayList<>();

    @Override
    public int onStartCommand(android.content.Intent it, int f, int id) {
        String action = (it != null) ? it.getAction() : "";

        // Unselect Fix: যখন সব অ্যাপ ফাঁকা হয়ে যাবে, তখন ভিপিএন পুরোপুরি ক্লোজ হবে
        if ("STOP".equals(action) || blockedApps.isEmpty()) {
            stopVpn();
            return START_NOT_STICKY;
        }

        establishVpn();
        return START_STICKY;
    }

    private void establishVpn() {
        try {
            if (vpn != null) vpn.close(); // পুরানো টানেল ভেঙে নতুন বানাবে
            Builder b = new Builder().setSession("NetAssistant").addAddress("10.0.0.2", 32).addRoute("0.0.0.0", 0);

            for (String k : blockedApps) { 
                b.addAllowedApplication(k); 
            }
            vpn = b.establish();

            showNotif("Service is Running....");

            new Thread(() -> {
                try {
                    java.io.FileInputStream in = new java.io.FileInputStream(vpn.getFileDescriptor());
                    byte[] buf = new byte[2048];
                    while (vpn != null) {
                        int l = in.read(buf);
                        if (l > 0) {
                            String d = new String(buf, 0, l, "UTF-8");
                            if (d.contains("Host:")) {
                                String captured = "Captured: " + d.substring(d.indexOf("Host:"), Math.min(d.length(), d.indexOf("Host:") + 50)).trim();
                                logList.add(0, captured);
                            }
                        }
                    }
                } catch (Exception e) {}
            }).start();
        } catch (Exception e) {}
    }

    private void stopVpn() {
        try { if (vpn != null) { vpn.close(); vpn = null; } } catch (Exception e) {}
        stopForeground(true);
        stopSelf();
    }

    @Override
    public void onDestroy() {
        stopVpn();
        super.onDestroy();
    }

    private void showNotif(String msg) {
        android.app.NotificationManager nm = (android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE);
        if (android.os.Build.VERSION.SDK_INT >= 26) nm.createNotificationChannel(new android.app.NotificationChannel("net_ch", "Monitor", 3));
        android.app.PendingIntent pi = android.app.PendingIntent.getActivity(this, 0, new android.content.Intent(this, MainActivity.class).setAction("SHOW_LOGS"), android.app.PendingIntent.FLAG_UPDATE_CURRENT | android.app.PendingIntent.FLAG_IMMUTABLE);
        startForeground(1, new android.app.Notification.Builder(this, "net_ch")
            .setSmallIcon(android.R.drawable.ic_menu_search)
            .setContentTitle("Network Assistant")
            .setContentText(msg)
            .setContentIntent(pi).build());
    }
}
